SELECT CASE WHEN pu_zone IS NULL OR TRIM(pu_zone) = '' THEN 'Unknown' ELSE pu_zone END AS pu_zone, CASE WHEN pu_borough IS NULL OR TRIM(pu_borough) = '' THEN 'Unknown' ELSE pu_borough END AS pu_borough, COUNT(*) AS trips, SUM(total_amount) AS revenue_usd, AVG(CASE WHEN total_amount IS NOT NULL AND total_amount > 0 THEN total_amount END) AS avg_total_usd, 100.0 * COUNT(*) / SUM(COUNT(*)) OVER () AS share_trips_pct FROM tlc.taxi.yellow_trips WHERE data_month IN (DATE '2026-01-01', DATE '2026-02-01', DATE '2026-03-01') AND data_month IS NOT NULL GROUP BY CASE WHEN pu_zone IS NULL OR TRIM(pu_zone) = '' THEN 'Unknown' ELSE pu_zone END, CASE WHEN pu_borough IS NULL OR TRIM(pu_borough) = '' THEN 'Unknown' ELSE pu_borough END ORDER BY trips DESC LIMIT 12
